 static void RunCore(){int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception("K FAIL: "+label);checks++;Console.WriteLine("K PASS: "+label);}var filter=new OverviewTabK{Types=["Raider"],Exceptions=["friendly:hide","hostile:show"]};Check(!filter.Allows("Raider",true,true,false,false),"first matching exception hides friendly hostile");filter.Exceptions.Reverse();Check(filter.Allows("Raider",true,true,false,false),"priority change controls conflicting states");Check(!filter.Allows("Asteroid",false,false,false,false),"type filter rejects resources");filter.Exceptions.Insert(0,"selected:show");Check(filter.Allows("Asteroid",false,false,false,true),"selected exception overrides type filter");var copy=filter.Copy();copy.Types.Add("Asteroid");Check(!filter.Types.Contains("Asteroid"),"tab copy owns filter lists");Check(OverviewTabK.Defaults().Count==5,"travel and resource defaults provided");
 var parts=new List<decimal>{12};Check(StackPresentationK.Split(parts,0,3)&&parts.SequenceEqual(new decimal[]{9,3}),"split allocates authoritative quantity");Check(!StackPresentationK.Split(parts,0,20)&&parts.Sum()==12,"invalid split leaves stock unchanged");Check(StackPresentationK.Reconcile(5,parts).Sum()==5&&StackPresentationK.Reconcile(20,parts).Sum()==20,"external changes reconcile without duplication");
 FittingModule a=new FittingModule("weapon",0,"rail","high"),b=new FittingModule("weapon",1,"rail","high"),c=new FittingModule("utility",2,"miner","high");var rack=new RackLayoutK();rack.Reconcile([a,b,c]);int oldB=rack.Position(b),oldC=rack.Position(c);rack.Reconcile([b,c]);Check(rack.Position(b)==oldB&&rack.Position(c)==oldC,"removing a module preserves surviving flight positions");rack.Reconcile([a,b,c]);Check(rack.Position(a)==0,"refitting uses vacant slot");var pref=JsonSerializer.Deserialize<ClientPreferencesK>(JsonSerializer.Serialize(new ClientPreferencesK{Racks=new(){["hull"]=rack}}))!;Check(pref.Racks["hull"].Position(c)==oldC,"rack layout roundtrip");
 var w=new DemoWorld();w.NewGame(0);w.Hangar["ammo"]=12;w.Hangar["miner"]=1;decimal ammo=w.StackCount("ammo",false),miner=w.StackCount("miner",false);Check(w.TransferBatchK(new[]{("ammo",3m),("miner",1m)},true)==""&&w.StackCount("ammo",false)==ammo+3&&w.StackCount("miner",false)==miner+1,"multi-item batch transfers exact selected quantities");ammo=w.StackCount("ammo",false);Check(w.TransferBatchK(new[]{("ammo",3m),("miner",2m)},true).Length>0&&w.StackCount("ammo",false)==ammo,"unavailable later item leaves earlier item untouched");w.Hangar["rail"]=1;w.Player.Ore=w.Player.CargoMax;Check(w.TransferBatchK(new[]{("ammo",1m),("rail",1m)},true).Length>0&&w.Hangar["rail"]==1,"combined capacity preflight prevents partial transfer");Check(w.TransferBatchK(new[]{("ammo",.5m)},true).Length>0,"discrete item fractions rejected");w.Player.Ore=0;w.Screen=ViewMode.Space;Check(w.TransferBatchK(new[]{("ammo",1m)},true).Length>0,"remote station batch rejected");
 var win=new DesktopWindow{Kind=ViewMode.OverviewJ,InstanceId="test",Width=460,Height=600,TabsK=OverviewTabK.Defaults(),TabK=3,SplitStacksK=new(){["cargo/ammo"]=[9,3]},CompareKeysK=["item/rail"],LocationK="container:test"};var round=JsonSerializer.Deserialize<DesktopWindow>(JsonSerializer.Serialize(win))!;Check(round.TabsK.Count==5&&round.TabK==3&&round.LocationK==win.LocationK&&round.SplitStacksK["cargo/ammo"].Sum()==12,"new desktop view state roundtrip");var simulation=new FittingSimulation(w.Player);var balance=w.Balance;var inventory=w.CargoItems.ToDictionary(p=>p.Key,p=>p.Value);simulation.Stock();simulation.World.Player.Ore=123;Check(w.Balance==balance&&w.CargoItems.SequenceEqual(inventory)&&w.Player.Ore==0,"simulation stock and ship changes isolated from live world");var missionWorld=new DemoWorld();missionWorld.NewGame(0);missionWorld.Player.CargoMax=100000;var agent=AgentCatalog38.Agents.First(a=>a.Station=="aster"&&a.Level==1&&a.Division==AgentDivision38.Mining);missionWorld.RequestMission38(agent.Id);var mission=missionWorld.AgentsState.Missions.Last();missionWorld.AcceptMission38(mission.Id);mission.Cargo=50;mission.Harvested=50;string missionId="mission-cargo:"+mission.Id;Check(missionWorld.TransferBatchK(new[]{(missionId,12.5m)},false)==""&&mission.Cargo==37.5f&&mission.Hangars[missionWorld.StationKey44]==12.5f,"fractional mission batch retains contract identity");missionWorld.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.InventoryDisplayCount(missionId,false)==37.5m,"batch mission cargo survives game save reload");Console.WriteLine(checks+" Stage K backend checks passed.");}
}
